def deeper_changes(records):
    anchors = {v['video_id']: r['fixed']['creator_id'] for r in records
               if r['fixed']['unit_type'] == 'profile' for v in r['fixed']['videos']}
    changes = {}
    for anchor, label, domains, specs, ids, confidence, finding, uncertainty in PROFILES:
        changes['profile/'+anchors[anchor]] = dict(proposed_label=label,
            proposed_domains=domains.split(), proposed_specializations=specs.split(),
            selected_video_ids=ids.split(), proxy_video_ids=[], confidence=confidence,
            reason=finding, manual_question=uncertainty, unresolved_uncertainty=uncertainty)
    for anchor, topic, label, ids, proxy, confidence, finding, uncertainty in AFFINITIES:
        changes['affinity/'+anchors[anchor]+'/'+topic] = dict(proposed_label=label,
            selected_video_ids=ids.split(), proxy_video_ids=proxy.split(), confidence=confidence,
            reason=finding, manual_question=uncertainty, unresolved_uncertainty=uncertainty)
    return changes
